ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mdm http://www.etb.com.co/Gateway/MDM_Data_Services
var numFactura = if (payload.NotifyBillInput.Request.Source.system == "OpenFlex") payload.NotifyBillInput.Request.ServiceBill.billNumber else payload.NotifyBillInput.Request.EquipmentBill.number
---
{
    soapenv#"Envelope": {
        soapenv#"Header": null,
        soapenv#"Body": {
            mdm#"Set_FacturaOnLine": {
                mdm#"WSRequestHeader": {
                    mdm#"system": {
                        mdm#"name": p('mdmDataServices.name'),
                        mdm#"correlationId": attributes.headers.'x-correlation-id',
                        mdm#"processingServer": p('mdmDataServices.processingServer')
                    }
                },
                mdm#"WSRequestBody": {
                   (mdm#"codigo_barras": payload.NotifyBillInput.Request.ServiceBill.barcode) if (!isEmpty(payload.NotifyBillInput.Request.EquipmentBill.barcode)),
                   (mdm#"numero_cuenta_facturacion": payload.NotifyBillInput.Request.Source.billingAccount) if (!isEmpty(payload.NotifyBillInput.Request.Source.billingAccount)),
                   (mdm#"numero_factura": numFactura) if (!isEmpty(numFactura)),
                    mdm#"fecha_oportuna_pago": payload.NotifyBillInput.Request.EquipmentBill.paymentDueDate,
                    mdm#"fecha_limite_Pago": payload.NotifyBillInput.Request.EquipmentBill.paymentDeadline,
                   (mdm#"valor": payload.NotifyBillInput.Request.EquipmentBill.amount) if (!isEmpty(payload.NotifyBillInput.Request.EquipmentBill.amount)),
                    mdm#"origen_factura": payload.NotifyBillInput.Request.Source.system,
                   (mdm#"periodo_facturado": payload.NotifyBillInput.Request.ServiceBill.billPeriod) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.billPeriod)),
                    mdm#"id_registro": attributes.headers.'x-correlation-id',
                   (mdm#"estado_factura": payload.NotifyBillInput.Request.ServiceBill.billStatus) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.billStatus)),
                   (mdm#"numero_conexion": payload.NotifyBillInput.Request.ServiceBill.connectionNumber) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.connectionNumber)),
                    mdm#"numero_identificacion": payload.NotifyBillInput.Request.Customer.id,
                    mdm#"nombre_cliente": payload.NotifyBillInput.Request.Customer.name
                }
            }
        }
    }
}

%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mdm http://www.etb.com.co/Gateway/MDM_Data_Services
import substring from dw::core::Strings
---
{
    soapenv#"Envelope": {
        soapenv#"Header": null,
        soapenv#"Body": {
            mdm#"Set_FacturaOnLine": {
                mdm#"WSRequestHeader": {
                    mdm#"system": {
                        mdm#"name": p('mdmDataServices.name'),
                        mdm#"correlationId": attributes.headers.'x-correlation-id',
                        mdm#"processingServer": p('mdmDataServices.processingServer')
                    }
                },
                mdm#"WSRequestBody": {
                   (mdm#"codigo_barras": payload.NotifyBillInput.Request.ServiceBill.barcode) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.barcode)),
                   (mdm#"numero_cuenta_facturacion": payload.NotifyBillInput.Request.Source.billingAccount) if (!isEmpty(payload.NotifyBillInput.Request.Source.billingAccount)),
                    mdm#"numero_factura": payload.NotifyBillInput.Request.ServiceBill.number,
                    mdm#"fecha_oportuna_pago": payload.NotifyBillInput.Request.ServiceBill.paymentDueDate,
                    mdm#"fecha_limite_Pago": payload.NotifyBillInput.Request.ServiceBill.paymentDeadline,
                   (mdm#"valor": payload.NotifyBillInput.Request.ServiceBill.amount) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.amount)),
                    mdm#"origen_factura": payload.NotifyBillInput.Request.Source.system,
                    mdm#"numero_ciclo": if (payload.NotifyBillInput.Request.Source.system == "08")  substring(payload.NotifyBillInput.Request.ServiceBill.billPeriod, 4, 6) else "",
                    mdm#"periodo_facturado": if (payload.NotifyBillInput.Request.Source.system == "08")  ("20" ++ substring(payload.NotifyBillInput.Request.ServiceBill.billPeriod, 0, 4)) else "",
                    mdm#"id_registro": attributes.headers.'x-correlation-id',
                   (mdm#"estado_factura": payload.NotifyBillInput.Request.ServiceBill.billStatus) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.billStatus)),
                   (mdm#"numero_conexion": payload.NotifyBillInput.Request.ServiceBill.connectionNumber) if (!isEmpty(payload.NotifyBillInput.Request.ServiceBill.connectionNumber)),
                    mdm#"numero_identificacion": payload.NotifyBillInput.Request.Customer.id,
                    mdm#"nombre_cliente": payload.NotifyBillInput.Request.Customer.name
                }
            }
        }
    }
}
